import numpy as np

def kernel(x, g, eps):
    M, N = x.shape
    y = np.zeros_like(x, dtype=np.float32)
    tile_rows = 128
    tile_cols = 512

    # First pass: compute RMS norm for each row
    rms = np.zeros(M, dtype=np.float32)
    for i in range(0, M, tile_rows):
        end_i = min(i + tile_rows, M)
        for j in range(0, N, tile_cols):
            end_j = min(j + tile_cols, N)
            x_tile = x[i:end_i, j:end_j]
            for row in range(end_i - i):
                for col in range(end_j - j):
                    rms[i + row] += x_tile[row, col] ** 2

    # Compute RMS norm
    rms = np.sqrt(rms / N + eps)

    # Second pass: normalize and scale
    for i in range(0, M, tile_rows):
        end_i = min(i + tile_rows, M)
        for j in range(0, N, tile_cols):
            end_j = min(j + tile_cols, N)
            x_tile = x[i:end_i, j:end_j]
            for r in range(end_i - i):
                for c in range(end_j - j):
                    y[i + r, j + c] = x_tile[r, c] / rms[i + r] * g[j + c]

    return y
